<script>

import serverUrl from '../../config';
import { mapActions, mapGetters } from "vuex";
import io from "socket.io-client";
import * as Types from "../../store/types";
import { eventBus } from "../../main";
import moment from 'moment';

export default {
  props: [
    'id',
    'name',
    'image',
    'commentsArr',
    'likeNumber',
    'likesArr',
    'owner',
    'isEdit2',
    'ownerName',
    'date',
    'ownerId',
    'ownerImage'
  ],

  data() {
    return {
      // حالة المكون
      isHovered: false,
      imageLoaded: false,
      isLiking: false,
      showComments: false,
      commentLoading: false,
      editLoading: false,
      selectedImage: null,
      imagePreview: null,
      
      // بيانات النماذج
      postText: "",
      comment: "",
      newComment: "",
      
      // حالة الحوارات
      dialog: false,
      dialogDelete: false,
      
      // بيانات الإعجاب
      likeColor: 'gray',
      
      // بيانات الشبكة
      socket: io(serverUrl, {
        query: { token: localStorage.getItem("token") },
      }),
      urls: serverUrl,
      defaultAvatar: require('@/assets/avatar.png')
    };
  },

  computed: {
    getOwnerImageUrl() {
      console.log('owner1: ', `${this.urls}/profile-image/${this.$route.params.id}.PNG`)
    if (this.ownerId) {
      console.log('owner: ', `${this.urls}/profile-image/${this.ownerId }.PNG`)
      return this.ownerImage?.startsWith('http') 
        ? this.ownerImage 
        : `${this.urls}/profile-image/${this.ownerId || this.$route.params.id}.PNG`;
    }
    
    // صورة افتراضية إذا لم توجد صورة
    return `https://ui-avatars.com/api/?name=${encodeURIComponent(this.ownerName)}&background=e91e63&color=fff&size=128`;
  },
    ...mapGetters({
      // getCommentsGetter: Types.GET_COMMENTS,
    }),
    
    isOwner() {
      return this.owner == localStorage.getItem('userID');
    }
  },

  methods: {
    ...mapActions({
      getCommets: Types.GET_COMMENTS,
    }),

    onPostClick(id) {
      console.log('post.vue id', id);
    },

    postOwner(owner) {
      return owner == localStorage.getItem('userID');
    },

    addComment(data) {
      this.socket.emit('new-comment', data);
    },

    showPosts() {
      this.showComments = !this.showComments;
    },

    addRemoveLike(postID) {
      this.isLiking = true;
      this.likeColor = this.likeColor == 'gray' ? '#1976d2' : 'gray';
      this.socket.emit('add-remove-like', postID);
      
      setTimeout(() => {
        this.isLiking = false;
      }, 300);
    },

    EditPost(owner) {
      this.editLoading = true;
      this.socket.emit('edit-post', {
        text: this.postText,
        id: this.id,
        owner: owner,
        image: this.selectedImage
      });
      
      setTimeout(() => {
        this.editLoading = false;
        this.dialogDelete = false;
        this.selectedImage = null;
        this.imagePreview = null;
      }, 1000);
    },

    openEditDialog() {
      this.postText = this.name;
      this.dialogDelete = true;
    },

    confirmDelete() {
      if (confirm('هل أنت متأكد من حذف هذا المنشور؟')) {
        this.socket.emit('delete-post', {
          postid: this.id,
          ownerid: this.owner
        });
      }
    },

    onFileSelected(event) {
      this.selectedImage = event.target.files[0];
      this.imagePreview = URL.createObjectURL(this.selectedImage);
    },

    onUserProfile(id) {
      this.$router.push({
        name: 'userProfile',
        params: { id: id }
      });
    },

    postDate(date) {
      moment.locale(this.$i18n.locale);
      return moment(date).format('MM/DD/YYYY');
    },

    toLocalData(date) {
      const d = new Date(date);
      return moment(d).fromNow();
    },

    expandImage() {
      // فتح الصورة في عرض كامل
      this.$emit('expand-image', this.image);
    },

    shareOnFacebook() {
      window.open(`https://www.facebook.com/sharer/sharer.php?u=${window.location.href}`, '_blank');
    },

    shareOnTwitter() {
      window.open(`https://twitter.com/intent/tweet?text=${this.name}&url=${window.location.href}`, '_blank');
    },

    copyLink() {
      navigator.clipboard.writeText(window.location.href);
      this.$toast?.success('تم نسخ الرابط');
    },
    

   handleImageError(event) {
   if (event.target) {
      event.target.src = this.defaultAvatar;
    } else {
      // إذا كان event هو كائن Vuetify:
      return this.defaultAvatar;
    }
  },
  
  // التوجه لصفحة المستخدم عند النقر على الصورة

  },

  created() {
    // التحقق من الإعجابات السابقة
    for (let i = 0; i < this.likesArr.length; i++) {
      if (localStorage.getItem('userID') == this.likesArr[i].user) {
        this.likeColor = '#1976d2';
      }
    }

    // مستمعي Socket.io
    this.socket.on('new-comment-posted', data => {
      this.$store.commit('addComment', data);
    });

    this.socket.on('add-like', like => {
      this.$store.commit('addLike', like);
    });

    this.socket.on('remove-like', like => {
      this.$store.commit('removeLike', like);
    });
  },

  mounted() {
    // التمرير إلى البوست عند الطلب
    eventBus.$on('onNavPost', post => {
      let id = post.data.post._id;
      var element = this.$refs[id];
      if (element) {
        var top = element.offsetTop;
        window.scrollTo({ top, behavior: 'smooth' });
      }
    });
  },

  beforeDestroy() {
    // تنظيف مستمعي Socket
    this.socket.off('new-comment-posted');
    this.socket.off('add-like');
    this.socket.off('remove-like');
    
    // تنظيف روابط الصور
    if (this.imagePreview) {
      URL.revokeObjectURL(this.imagePreview);
    }
  }
};
</script>

