<template>
  <v-dialog
    v-model="show"
    max-width="500px"
    fullscreen
    transition="dialog-bottom-transition"
    :overlay-opacity="0.8"
    :overlay-color="isDarkMode ? '#121212' : '#ffffff'"
    content-class="mobile-post-dialog"
    persistent
  >
    <div :key="localReRenderComponent" class="mobile-post-container">
      <!-- زر إنشاء منشور -->
      <transition name="slide-up">
        <div
          v-if="!isPosting && !applyPost"
          :style="buttonStyle"
          class="floating-button"
        >
          <!-- <v-btn
            class="create-post-btn"
            large
            fab
            color="primary"
            @click="startSteps"
            elevation="8"
            :ripple="{ center: true }"
          >
            <v-icon large>mdi-pencil-plus</v-icon>
          </v-btn> -->
        </div>
      </transition>

      <!-- نموذج إنشاء المنشور -->
      <transition name="slide-fade-up">
        <div v-if="isPosting && !applyPost" class="post-form-mobile">
          <v-sheet
            class="post-sheet-mobile"
            color="grey lighten-4"
            elevation="0"
          >
            <!-- Header مع عنوان وأزرار تحكم -->
            <div class="sheet-header-mobile">
              <v-btn
                icon
                @click="cancel"
                class="close-btn"
              >
                <v-icon>mdi-close</v-icon>
              </v-btn>
              
              <h2 class="text-h6 font-weight-bold">
                <v-icon color="primary" class="mr-1">mdi-post-outline</v-icon>
                منشور جديد
              </h2>
              
              <v-btn
                icon
                @click="minimize"
                class="minimize-btn"
                v-if="currentStep > 1"
              >
                <v-icon>mdi-chevron-down</v-icon>
              </v-btn>
            </div>

            <v-divider></v-divider>

            <!-- Progress Bar -->
            <div class="progress-bar-container">
              <v-progress-linear
                :value="progressValue"
                height="4"
                :color="progressColor"
                striped
              ></v-progress-linear>
              <span class="progress-step">{{ currentStep }}/4</span>
            </div>

            <!-- Vertical Stepper محسن للموبايل -->
            <v-stepper
              v-model="currentStep"
              vertical
              class="mobile-stepper"
              flat
              tile
            >
              <!-- الخطوة 1: العنوان -->
              <v-stepper-step
                :complete="currentStep > 1"
                step="1"
                editable
                :rules="[() => !titleError]"
                class="mobile-step"
                :class="{ 'step-active': currentStep === 1 }"
              >
                <div class="step-header">
                  <v-icon color="primary" small class="step-icon">mdi-format-title</v-icon>
                  <span class="step-title">العنوان</span>
                </div>
                <small class="step-desc">أدخل عنواناً جذاباً لمنشورك</small>
              </v-stepper-step>

              <v-stepper-content step="1" class="mobile-step-content">
                <v-text-field
                  v-model="postTitle"
                  label="عنوان المنشور"
                  placeholder="مثلاً: رحلتي إلى ..."
                  counter="25"
                  :error-messages="titleErrorMessage"
                  :success="titleValid"
                  color="primary"
                  outlined
                  dense
                  class="mobile-title-input"
                  autofocus
                  @input="validateTitle"
                  @keyup.enter="goToStep(2)"
                >
                  <template v-slot:prepend>
                    <v-icon color="primary" small>mdi-pencil</v-icon>
                  </template>
                </v-text-field>

                <div class="mobile-step-actions">
                  <v-btn
                    color="primary"
                    @click="goToStep(2)"
                    :disabled="!titleValid"
                    block
                    large
                    elevation="2"
                    class="action-btn"
                  >
                    متابعة
                    <v-icon right>mdi-arrow-right</v-icon>
                  </v-btn>
                </div>
              </v-stepper-content>

              <!-- الخطوة 2: الصورة -->
              <v-stepper-step
                :complete="currentStep > 2"
                step="2"
                :rules="[() => imageValid]"
                class="mobile-step"
                :class="{ 'step-active': currentStep === 2 }"
              >
                <div class="step-header">
                  <v-icon color="primary" small class="step-icon">mdi-image</v-icon>
                  <span class="step-title">الصورة</span>
                </div>
                <small class="step-desc">اختر صورة معبرة</small>
              </v-stepper-step>

              <v-stepper-content step="2" class="mobile-step-content">
                <v-card
                  class="mobile-image-upload"
                  :class="{ 'has-image': selectedFile }"
                  @click="$refs.fileInput.click()"
                  outlined
                  :ripple="false"
                >
                  <div v-if="!selectedFile" class="upload-placeholder-mobile">
                    <v-icon size="48" color="primary lighten-2">mdi-image-plus</v-icon>
                    <span class="upload-text">انقر لاختيار صورة</span>
                    <span class="upload-hint">jpg, png, gif (max 5MB)</span>
                  </div>

                  <div v-else class="image-preview-wrapper-mobile">
                    <img
                      ref="previewImage"
                      class="image-preview-mobile"
                      :src="imagePreview"
                      alt="Preview"
                    />
                    <div class="image-overlay-mobile">
                      <v-btn
                        icon
                        small
                        color="white"
                        @click.stop="clearImage"
                        class="remove-image-btn"
                      >
                        <v-icon small>mdi-close</v-icon>
                      </v-btn>
                    </div>
                  </div>

                  <input
                    ref="fileInput"
                    type="file"
                    accept="image/*"
                    class="hidden-input"
                    @change="handleImageSelect"
                  />
                </v-card>

                <div class="mobile-step-actions">
                  <v-btn
                    text
                    @click="goToStep(1)"
                    class="back-btn"
                    block
                  >
                    <v-icon left>mdi-arrow-left</v-icon>
                    السابق
                  </v-btn>
                  <v-btn
                    color="primary"
                    @click="goToStep(3)"
                    :disabled="!imageValid"
                    block
                    large
                    elevation="2"
                    class="action-btn mt-2"
                  >
                    متابعة
                    <v-icon right>mdi-arrow-right</v-icon>
                  </v-btn>
                </div>
              </v-stepper-content>

              <!-- الخطوة 3: معاينة -->
              <v-stepper-step
                :complete="currentStep > 3"
                step="3"
                class="mobile-step"
                :class="{ 'step-active': currentStep === 3 }"
              >
                <div class="step-header">
                  <v-icon color="primary" small class="step-icon">mdi-eye</v-icon>
                  <span class="step-title">معاينة</span>
                </div>
                <small class="step-desc">راجع منشورك</small>
              </v-stepper-step>

              <v-stepper-content step="3" class="mobile-step-content">
                <div class="preview-wrapper">
                  <PostReview
                    :image="imagePreview"
                    :name="postTitle"
                    :ownerName="username"
                    class="mobile-preview-card"
                  />
                </div>

                <div class="mobile-step-actions">
                  <v-btn
                    text
                    @click="goToStep(2)"
                    class="back-btn"
                    block
                  >
                    <v-icon left>mdi-arrow-left</v-icon>
                    تعديل
                  </v-btn>
                  <v-btn
                    color="primary"
                    @click="goToStep(4)"
                    block
                    large
                    elevation="2"
                    class="action-btn mt-2"
                  >
                    متابعة
                    <v-icon right>mdi-arrow-right</v-icon>
                  </v-btn>
                </div>
              </v-stepper-content>

              <!-- الخطوة 4: النشر -->
              <v-stepper-step step="4" class="mobile-step">
                <div class="step-header">
                  <v-icon color="primary" small class="step-icon">mdi-send</v-icon>
                  <span class="step-title">نشر</span>
                </div>
                <small class="step-desc">انشر منشورك الآن</small>
              </v-stepper-step>

              <v-stepper-content step="4" class="mobile-step-content">
                <v-alert
                  type="info"
                  colored-border
                  border="left"
                  elevation="2"
                  class="publish-alert-mobile"
                >
                  <div class="d-flex align-center">
                    <v-icon color="info" class="mr-2">mdi-information</v-icon>
                    <span>تأكد من صحة المحتوى قبل النشر</span>
                  </div>
                </v-alert>

                <div class="mobile-step-actions">
                  <v-btn
                    text
                    @click="goToStep(3)"
                    class="back-btn"
                    block
                  >
                    <v-icon left>mdi-arrow-left</v-icon>
                    مراجعة
                  </v-btn>
                  <v-btn
                    color="success"
                    @click="publishPost"
                    :loading="postLoading"
                    block
                    large
                    elevation="2"
                    class="publish-btn mt-2"
                  >
                    <v-icon left>mdi-check</v-icon>
                    نشر المنشور
                  </v-btn>
                </div>
              </v-stepper-content>
            </v-stepper>
          </v-sheet>
        </div>
      </transition>

      <!-- مؤشر تحميل أثناء النشر -->
      <transition name="fade">
        <div v-if="applyPost" class="mobile-loading-overlay">
          <v-card class="mobile-loading-card" elevation="12">
            <v-progress-circular
              indeterminate
              size="48"
              color="primary"
            ></v-progress-circular>
            <h3 class="text-subtitle-1 mt-3">جاري النشر...</h3>
            <p class="text-caption grey--text">قد يستغرق ذلك لحظات</p>
          </v-card>
        </div>
      </transition>

      <!-- رسالة نجاح -->
      <v-snackbar
        v-model="showSuccess"
        :timeout="3000"
        color="success"
        bottom
        right
      >
        <v-icon left>mdi-check-circle</v-icon>
        {{ successMessage }}
      </v-snackbar>
    </div>
  </v-dialog>
</template>

<script>
import serverUrl from '../../config';
import PostReview from '../post/postReview.vue';
import { mapGetters, mapMutations } from 'vuex';
import { eventBus } from '../../main';
import axios from 'axios';
import io from 'socket.io-client';

export default {
  name: 'MobileCreatePost',

  components: {
    PostReview
  },

  props: {
    position: {
      type: String,
      default: 'fixed'
    },
    maxWidth: {
      type: Number,
      default: 500
    },
    marginLeft: {
      type: String,
      default: '16px'
    },
    value: {
      type: Boolean,
      default: false
    }
  },

  data() {
    return {
      // حالة النموذج
      currentStep: 1,
      postTitle: '',
      selectedFile: null,
      imagePreview: null,
      
      // حالة النشر
      isPosting: false,
      postLoading: false,
      applyPost: false,
      
      // حالة التحقق
      titleError: false,
      titleErrorMessage: '',
      imageValid: false,
      
      // تقدم النشر
      progressValue: 0,
      
      // حالة إعادة الرسم
      localReRenderComponent: 0,
      
      // رسائل النجاح
      showSuccess: false,
      successMessage: '',
      
      // إعدادات الموبايل
      isKeyboardOpen: false,
      isDarkMode: false,
      
      // Socket.io
      socket: io(serverUrl, {
        query: { token: localStorage.getItem('token') }
      }),
      
      urls: serverUrl,
      
      // عناصر DOM
      stepElements: {
        step1: null,
        step2: null,
        step3: null
      },
      
      divBorders: {
        div1: null,
        div2: null,
        div3: null
      },
      
      // متغيرات الحالة القديمة (للتوافق)
      step0: 0,
      step2: 0,
      exutdedFunction1: false,
      exutdedFunction10: false
    };
  },

  computed: {
    ...mapGetters({
      username: 'getUsername',
      renderComponent: 'getrerendercomponent'
    }),

    show: {
      get() {
        return this.value;
      },
      set(value) {
        this.$emit('input', value);
        if (!value) {
          this.reset();
        }
      }
    },

    buttonStyle() {
      return {
        'margin-left': this.marginLeft,
        'margin-top': '-55px',
        'position': this.position,
        'z-index': 1001
      };
    },

    progressColor() {
      if (this.progressValue === 100) return 'success';
      if (this.progressValue >= 50) return 'info';
      return 'primary';
    },

    titleValid() {
      return this.postTitle && 
             this.postTitle.length <= 25 && 
             this.postTitle.length >= 3;
    }
  },

  methods: {
    ...mapMutations({
      setpostProgress: 'setpostProgress'
    }),

    // بدء عملية إنشاء المنشور
    startSteps() {
      this.isPosting = true;
      this.currentStep = 1;
      this.progressValue = 0;
      this.show = true;
      
      // منع التمرير في الخلفية
      document.body.style.overflow = 'hidden';
    },

    // التنقل بين الخطوات
    goToStep(step) {
      if (step === 2 && !this.validateTitle()) {
        this.showValidationError('الرجاء إدخال عنوان صحيح');
        return;
      }
      
      if (step === 3 && !this.selectedFile) {
        this.showValidationError('الرجاء اختيار صورة');
        return;
      }

      this.currentStep = step;
      this.updateProgress();
      
      // تحديث حالة التحقق للتوافق مع الكود القديم
      this.updateLegacyState(step);
    },

    // تحديث حالة التحقق القديمة
    updateLegacyState(step) {
      if (step === 2) {
        this.isComplete1();
      } else if (step === 3) {
        this.isComplete2();
      }
    },

    // التحقق من صحة العنوان
    validateTitle() {
      if (!this.postTitle) {
        this.titleError = true;
        this.titleErrorMessage = 'العنوان مطلوب';
        this.step0 = 1;
        return false;
      }
      
      if (this.postTitle.length > 25) {
        this.titleError = true;
        this.titleErrorMessage = 'العنوان طويل جداً (الحد الأقصى 25 حرف)';
        this.step0 = 1;
        return false;
      }
      
      if (this.postTitle.length < 3) {
        this.titleError = true;
        this.titleErrorMessage = 'العنوان قصير جداً (الحد الأدنى 3 أحرف)';
        this.step0 = 1;
        return false;
      }
      
      this.titleError = false;
      this.titleErrorMessage = '';
      this.step0 = 0;
      return true;
    },

    // دوال التحقق القديمة (للتوافق)
    isComplete1() {
      if (this.postTitle === '' || this.postTitle.length > 25) {
        this.step0 = 1;
        this.updateStepIcon(0, 'alert');
        if (this.divBorders.div1) {
          this.divBorders.div1.style.borderLeft = '1px solid red';
        }
        
        if (this.exutdedFunction1) {
          this.exutdedFunction1 = false;
          if (this.progressValue > 0) {
            this.progressValue -= 25;
          }
        }
      } else {
        this.step0 = 0;
        this.updateStepIcon(0, 'check');
        if (this.divBorders.div1) {
          this.divBorders.div1.style.borderLeft = '1px solid blue';
        }
        
        if (!this.exutdedFunction1) {
          this.exutdedFunction1 = true;
          this.progressValue += 25;
        }
      }
      
      this.updateStepIcon(1, 'image');
    },

    isComplete2() {
      if (this.selectedFile) {
        this.step2 = 0;
        this.updateStepIcon(1, 'check');
        if (this.divBorders.div2) {
          this.divBorders.div2.style.borderLeft = '1px solid blue';
        }
        
        if (!this.exutdedFunction10) {
          this.exutdedFunction10 = true;
          this.progressValue += 25;
        }
      } else {
        this.updateStepIcon(1, 'alert');
        if (this.divBorders.div2) {
          this.divBorders.div2.style.borderLeft = '1px solid red';
        }
        this.step2 = 1;
        return;
      }
      
      this.updateStepIcon(2, 'preview');
    },

    isComplete3() {
      if (this.step0 === 0 && this.step2 === 0) {
        this.updateStepIcon(2, 'check');
        this.currentStep = 4;
        if (this.divBorders.div3) {
          this.divBorders.div3.style.borderLeft = '1px solid blue';
        }
      }
      
      if (this.step0 === 1) {
        this.currentStep = 1;
        this.scrollToStep('stepid1');
      }
      
      if (this.step2 === 1) {
        this.currentStep = 2;
        this.scrollToStep('stepid2');
      }
    },

    // تحديث أيقونة الخطوة
    updateStepIcon(stepIndex, type) {
      const x = document.querySelectorAll('span.v-stepper__step__step');
      if (x.length > stepIndex) {
        if (type === 'check') {
          x[stepIndex].innerHTML = '<i class="v-icon notranslate mdi mdi-check theme--light"></i>';
        } else if (type === 'alert') {
          x[stepIndex].innerHTML = '<i class="v-icon notranslate mdi mdi-alert theme--light"></i>';
        } else if (type === 'image') {
          x[stepIndex].innerHTML = this.getImageIcon();
        } else if (type === 'preview') {
          x[stepIndex].innerHTML = this.getPreviewIcon();
        }
      }
    },

    // أيقونات SVG
    getTextIcon() {
      return `<svg style="width:15px;height:15px;" viewBox="0 0 24 24">
        <path fill="#ffffff" d="M22,22H2V20H22V22M6.2,17.3L4.8,15.9L6.2,14.5L5.5,13.8L4.1,15.2L2.7,13.8L2,14.5L3.4,15.9L2,17.3L2.7,18L4.1,16.6L5.5,18L6.2,17.3M20.5,3L21.7,7.4L20.7,7.7C20.2,6.8 19.8,6 19.3,5.5C18.7,5 18.1,5 17.5,5H15V15.5C15,16 15,16.5 15.3,16.7C15.6,16.9 16.3,16.9 17,16.9V17.9H11V16.9C11.7,16.9 12.3,16.9 12.7,16.7C13,16.5 13,16 13,15.5V5H10.5C9.9,5 9.3,5 8.7,5.4C8.2,5.8 7.7,6.7 7.3,7.6L6.3,7.3L7.5,3H20.5Z"></path>
      </svg>`;
    },

    getImageIcon() {
      return `<svg style="width:15px;height:15px;" viewBox="0 0 24 24">
        <path fill="#ffffff" d="M22,16V4A2,2 0 0,0 20,2H8A2,2 0 0,0 6,4V16A2,2 0 0,0 8,18H20A2,2 0 0,0 22,16M11,12L13.03,14.71L16,11L20,16H8M2,6V20A2,2 0 0,0 4,22H18V20H4V6"></path>
      </svg>`;
    },

    getPreviewIcon() {
      return `<svg style="width:15px;height:15px;" viewBox="0 0 24 24">
        <path fill="#ffffff" d="M12,9A3,3 0 0,0 9,12A3,3 0 0,0 12,15A3,3 0 0,0 15,12A3,3 0 0,0 12,9M12,17A5,5 0 0,1 7,12A5,5 0 0,1 12,7A5,5 0 0,1 17,12A5,5 0 0,1 12,17M12,4.5C7,4.5 2.73,7.61 1,12C2.73,16.39 7,19.5 12,19.5C17,19.5 21.27,16.39 23,12C21.27,7.61 17,4.5 12,4.5Z"></path>
      </svg>`;
    },

    getPublishIcon() {
      return `<svg style="width:15px;height:15px;" viewBox="0 0 24 24">
        <path fill="#ffffff" d="M5,4V6H19V4H5M5,14H9V20H15V14H19L12,7L5,14Z"></path>
      </svg>`;
    },

    // معالجة اختيار الصورة
    handleImageSelect(event) {
      const file = event.target.files[0];
      
      if (!file) return;
      
      if (!file.type.startsWith('image/')) {
        this.showValidationError('الرجاء اختيار ملف صورة صالح');
        return;
      }
      
      if (file.size > 5 * 1024 * 1024) {
        this.showValidationError('حجم الصورة كبير جداً (الحد الأقصى 5MB)');
        return;
      }
      
      this.selectedFile = file;
      this.imageValid = true;
      
      const reader = new FileReader();
      reader.onload = (e) => {
        this.imagePreview = e.target.result;
        this.image = e.target.result; // للتوافق مع الكود القديم
      };
      reader.readAsDataURL(file);
    },

    // مسح الصورة المحددة
    clearImage() {
      this.selectedFile = null;
      this.imagePreview = null;
      this.image = null;
      this.imageValid = false;
      this.$refs.fileInput.value = '';
    },

    // تحديث شريط التقدم
    updateProgress() {
      switch (this.currentStep) {
        case 2:
          this.progressValue = 25;
          break;
        case 3:
          this.progressValue = 50;
          break;
        case 4:
          this.progressValue = 75;
          break;
        default:
          this.progressValue = 0;
      }
    },

    // التمرير إلى الخطوة المحددة
    scrollToStep(stepId) {
      const element = document.getElementById(stepId);
      if (element) {
        element.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }
    },

    // نشر المنشور
    async publishPost() {
      if (!this.selectedFile || !this.postTitle) {
        this.showValidationError('الرجاء إكمال جميع البيانات');
        return;
      }

      this.postLoading = true;
      this.progressValue = 90;
      this.applyPost = true;
      this.setpostProgress(true);

      const formData = new FormData();
      formData.append('file', this.selectedFile, this.selectedFile.name);
      formData.append('data', this.postTitle);

      try {
        const response = await axios.post(
          `${this.urls}/post/new-post`,
          formData,
          {
            headers: { 
              authorization: localStorage.getItem('token'),
              'Content-Type': 'multipart/form-data'
            }
          }
        );

        if (response.data.success) {
          this.progressValue = 100;
          this.socket.emit('new-post', response.data);
          
          this.successMessage = `تم نشر "${this.postTitle}" بنجاح`;
          this.showSuccess = true;
          
          setTimeout(() => {
            this.reset();
            this.$emit('post-created', response.data.post);
          }, 1500);
        }
      } catch (error) {
        console.error('خطأ في نشر المنشور:', error);
        this.showValidationError('حدث خطأ أثناء النشر');
        this.progressValue = 75;
      } finally {
        this.postLoading = false;
        this.applyPost = false;
        this.setpostProgress(false);
      }
    },

    // إعادة تعيين النموذج
    reset() {
      this.currentStep = 1;
      this.postTitle = '';
      this.selectedFile = null;
      this.imagePreview = null;
      this.image = null;
      this.isPosting = false;
      this.progressValue = 0;
      this.titleError = false;
      this.titleErrorMessage = '';
      this.imageValid = false;
      this.step0 = 0;
      this.step2 = 0;
      this.exutdedFunction1 = false;
      this.exutdedFunction10 = false;
      
      if (this.$refs.fileInput) {
        this.$refs.fileInput.value = '';
      }
      
      this.localReRenderComponent += 1;
      this.resetStepperIcons();
      
      // إعادة التمرير
      document.body.style.overflow = 'auto';
    },

    // إلغاء وإغلاق
    cancel() {
      this.reset();
      this.show = false;
      document.body.style.overflow = 'auto';
    },

    // تصغير النموذج
    minimize() {
      this.currentStep = 1;
      this.scrollToStep('stepid1');
    },

    // إعادة تعيين أيقونات الستيبر
    resetStepperIcons() {
      const x = document.querySelectorAll('span.v-stepper__step__step');
      if (x.length >= 4) {
        x[0].innerHTML = this.getTextIcon();
        x[1].innerHTML = this.getImageIcon();
        x[2].innerHTML = this.getPreviewIcon();
        x[3].innerHTML = this.getPublishIcon();
      }
    },

    // إظهار رسالة خطأ
    showValidationError(message) {
      this.$emit('error', message);
      // يمكن استخدام نظام إشعارات هنا
    },

    // دوال قديمة للتوافق
    testStep1() {
      if (this.currentStep === 0) return true;
      return this.step0 === 0;
    },

    testStep2() {
      return this.step2 === 0;
    },

    testStep3() {
      if (this.currentStep < 3) return true;
      return this.step0 === 0 && this.step2 === 0;
    },

    testTextField(v) {
      this.postTitle = v;
      return this.validateTitle() ? true : 'Max 25 characters';
    },

    previousStep2() {
      this.updateStepIcon(0, 'text');
    },

    previousStep3() {
      this.updateStepIcon(1, 'image');
    },

    onFileSelected01(event) {
      this.handleImageSelect(event);
    },

    savePost() {
      this.publishPost();
    }
  },

  watch: {
    currentStep(newStep) {
      this.updateProgress();
      if (newStep === 1) {
        this.updateStepIcon(0, 'text');
      }
    },

    postTitle() {
      this.validateTitle();
    },

    show(val) {
      if (val) {
        document.body.style.overflow = 'hidden';
      } else {
        document.body.style.overflow = 'auto';
      }
    }
  },

  mounted() {
     eventBus.$on('startPostStepper', (val) => {
      console.log('new new', val)
      if(val)
      this.startSteps()
    })
    this.$nextTick(() => {
      // تهيئة العناصر
      const x = document.querySelectorAll('span.v-stepper__step__step');
      if (x.length >= 4) {
        x[0].innerHTML = this.getTextIcon();
        x[1].innerHTML = this.getImageIcon();
        x[2].innerHTML = this.getPreviewIcon();
        x[3].innerHTML = this.getPublishIcon();
        
        this.stepElements.step1 = x[0];
        this.stepElements.step2 = x[1];
        this.stepElements.step3 = x[2];
      }

      const divBorder = document.querySelectorAll('div.v-stepper__content');
      this.divBorders.div1 = divBorder[0];
      this.divBorders.div2 = divBorder[1];
      this.divBorders.div3 = divBorder[2];
    });

    // كشف لوحة المفاتيح على الموبايل
    if (window.visualViewport) {
      window.visualViewport.addEventListener('resize', () => {
        this.isKeyboardOpen = window.visualViewport.height < window.innerHeight;
      });
    }

    // كشف الوضع المظلم
    const darkModeMediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
    this.isDarkMode = darkModeMediaQuery.matches;
    darkModeMediaQuery.addEventListener('change', (e) => {
      this.isDarkMode = e.matches;
    });

    // استماع للأحداث
    eventBus.$on('marginTopCustomPost', (margin) => {
      window.scrollTo({ top: margin, behavior: 'smooth' });
    });

     eventBus.$on('marginTopCustomPost', (margin) => {
      window.scrollTo({ top: margin, behavior: 'smooth' });
    });

  },

  beforeDestroy() {
    document.body.style.overflow = 'auto';
    eventBus.$off('marginTopCustomPost');
    if (this.socket) {
      this.socket.disconnect();
    }
  }
};
</script>

